import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matrix_mul_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matrixMulKernel(const float* __restrict__ A,
                                const float* __restrict__ B,
                                float* __restrict__ C,
                                int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        float val = 0.0f;
        for (int k = 0; k < N; k++) {
            val += A[row * N + k] * B[k * N + col];
        }
        C[row * N + col] = val;
    }
}

torch::Tensor matrix_mul_cuda(torch::Tensor A, torch::Tensor B) {
    int64_t N = A.size(0);

    auto options = torch::TensorOptions().dtype(A.dtype()).device(A.device());
    auto C = torch::zeros({N, N}, options);

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);

    matrixMulKernel<<<grid, block>>>(A.data_ptr<float>(),
                                     B.data_ptr<float>(),
                                     C.data_ptr<float>(),
                                     N);

    return C;
}
"""

matrix_mul_cpp_source = r"""
torch::Tensor matrix_mul_cuda(torch::Tensor A, torch::Tensor B);
"""

matrix_matmul = load_inline(
    name="matrix_matmul",
    cpp_sources=matrix_mul_cpp_source,
    cuda_sources=matrix_mul_source,
    functions=["matrix_mul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces torch.matmul with a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matrix_matmul.matrix_mul_cuda(A, B)
